-# Shuffle training data across PPO epochs
+# Shuffle training data before every PPO epoch.
+# When enabled with ppo_epochs > 1, shuffle runs inside each DP rank and
+# the whole train batch is balanced across DP ranks instead of each mini-batch.
+# With ppo_epochs = 1, trainer-side shuffle preserves mini-batch balancing.
 shuffle: ${oc.select:actor_rollout_ref.actor.shuffle,false}

